const settings = $('Set Digest Settings').first().json;
const lookbackHours = Number(settings.lookbackHours) || 24;
const minLength = Number(settings.minQuestionLength) || 12;
const fetchLimit = Number(settings.messageFetchLimit) || 100;
const questionWords = String(settings.questionWords || '')
  .split(',')
  .map(function (w) { return w.trim().toLowerCase(); })
  .filter(function (w) { return w.length > 0; });

const cutoffMs = Date.now() - lookbackHours * 60 * 60 * 1000;
const messages = $input.all().map(function (i) { return i.json; });

const repliedToIds = new Set();
for (const m of messages) {
  const ref = m.message_reference || {};
  if (ref.message_id) { repliedToIds.add(String(ref.message_id)); }
}

function isHumanMessage(m) {
  const isBot = Boolean(m.author && m.author.bot === true);
  const isSystem = m.type !== 0 && m.type !== 19;
  return !isBot && !isSystem;
}

function looksLikeQuestion(text) {
  const t = text.trim();
  if (t.length < minLength) { return false; }
  if (t.endsWith('?')) { return true; }
  const lower = t.toLowerCase();
  return questionWords.some(function (w) {
    return lower.indexOf(w + ' ') === 0 || lower.indexOf(w + "'") === 0;
  });
}

function hasThread(m) {
  const flags = Number(m.flags || 0);
  return Boolean(m.thread) || (flags & 32) === 32;
}

function answeredByMention(m) {
  const authorId = m.author && m.author.id ? String(m.author.id) : '';
  if (!authorId) { return false; }
  const askedAt = new Date(m.timestamp).getTime();
  return messages.some(function (other) {
    if (String(other.id) === String(m.id)) { return false; }
    if (new Date(other.timestamp).getTime() <= askedAt) { return false; }
    const mentions = Array.isArray(other.mentions) ? other.mentions : [];
    return mentions.some(function (u) { return String(u.id) === authorId; });
  });
}

const unanswered = [];
let messagesInWindow = 0;
let withContent = 0;

for (const m of messages) {
  if (String(m.content || '').length > 0) { withContent = withContent + 1; }
  const askedAt = new Date(m.timestamp).getTime();
  if (!(askedAt >= cutoffMs)) { continue; }
  messagesInWindow = messagesInWindow + 1;
  if (!isHumanMessage(m)) { continue; }
  const content = String(m.content || '');
  if (!looksLikeQuestion(content)) { continue; }
  if (repliedToIds.has(String(m.id))) { continue; }
  if (hasThread(m)) { continue; }
  if (answeredByMention(m)) { continue; }
  unanswered.push({
    messageId: String(m.id),
    authorName: (m.author && (m.author.global_name || m.author.username)) || 'unknown',
    authorId: (m.author && String(m.author.id)) || '',
    askedAt: m.timestamp,
    ageHours: Math.round(((Date.now() - askedAt) / 3600000) * 10) / 10,
    question: content.replace(/\s+/g, ' ').slice(0, 300)
  });
}

unanswered.sort(function (a, b) {
  return new Date(a.askedAt).getTime() - new Date(b.askedAt).getTime();
});

// Coverage evidence. Discord returns newest first and offers no before/after cursor,
// so the only honest thing to do is state how far back this run actually reached.
const oldestScannedAt = messages.length ? messages[messages.length - 1].timestamp : null;
const oldestMs = oldestScannedAt ? new Date(oldestScannedAt).getTime() : null;
const truncated = messages.length >= fetchLimit && oldestMs !== null && oldestMs > cutoffMs;

// A bot without the MESSAGE CONTENT intent still gets a 200, just with every content
// field blank. Without this check that looks identical to a quiet day.
const contentBlind = messages.length > 0 && withContent === 0;

let coverageNote;
if (messages.length === 0) {
  coverageNote = 'No messages returned at all. Check the channel ID and the bot View Channel permission.';
} else if (contentBlind) {
  coverageNote = 'WARNING: ' + messages.length + ' messages read but every content field was empty. The MESSAGE CONTENT privileged intent is almost certainly OFF, so no question can ever be detected.';
} else if (truncated) {
  coverageNote = 'PARTIAL COVERAGE: read the newest ' + messages.length + ' messages, back to ' + oldestScannedAt + ', which is still inside the ' + lookbackHours + 'h window. Older questions in the window were never read. Raise messageFetchLimit or run more often.';
} else {
  coverageNote = 'Full coverage: read ' + messages.length + ' messages back to ' + oldestScannedAt + ', past the ' + lookbackHours + 'h cutoff.';
}

return [{
  json: {
    unansweredCount: unanswered.length,
    messagesScanned: messages.length,
    messagesInWindow: messagesInWindow,
    messagesWithContent: withContent,
    fetchLimit: fetchLimit,
    oldestScannedAt: oldestScannedAt,
    truncated: truncated,
    contentBlind: contentBlind,
    coverageNote: coverageNote,
    lookbackHours: lookbackHours,
    scannedAt: new Date().toISOString(),
    questions: unanswered
  }
}];

const settings = $('Set Digest Settings').first().json;
const data = $input.first().json;
const guildId = String(settings.guildId || '');
const helpChannelId = String(settings.helpChannelId || '');
const helpChannelLabel = String(settings.helpChannelLabel || 'help');
const maxInMessage = Number(settings.maxQuestionsInMessage) || 15;
const digestDate = new Date().toISOString().slice(0, 10);

const questions = (data.questions || []).map(function (q) {
  return Object.assign({}, q, {
    digestDate: digestDate,
    jumpUrl: 'https://discord.com/channels/' + guildId + '/' + helpChannelId + '/' + q.messageId
  });
});

const shown = questions.slice(0, maxInMessage);
const lines = [];
lines.push('**Unanswered questions in #' + helpChannelLabel + '** (last ' + data.lookbackHours + 'h)');

// Report against what was actually read, never against a total this workflow cannot know.
lines.push(String(data.unansweredCount) + ' unanswered, out of ' + String(data.messagesInWindow) +
           ' messages read inside the window.');
if (data.truncated) {
  lines.push('WARNING: only the newest ' + String(data.fetchLimit) + ' messages were read, back to ' +
             String(data.oldestScannedAt) + '. Older questions in this window were NOT checked. ' +
             'Raise messageFetchLimit in Set Digest Settings.');
}
lines.push('');

shown.forEach(function (q, idx) {
  lines.push(String(idx + 1) + '. **' + q.authorName + '** (' + String(q.ageHours) + 'h ago): ' + q.question.slice(0, 160));
  lines.push(q.jumpUrl);
});

if (questions.length > shown.length) {
  lines.push('');
  lines.push('...and ' + String(questions.length - shown.length) + ' more. The full list is in the log sheet.');
}

let digestMessage = lines.join('\n');
if (digestMessage.length > 1900) {
  digestMessage = digestMessage.slice(0, 1890) + '\n...truncated';
}

return [{
  json: {
    digestMessage: digestMessage,
    digestDate: digestDate,
    unansweredCount: questions.length,
    coverageNote: data.coverageNote,
    truncated: data.truncated,
    questions: questions
  }
}];

